    @EventHandler( payloadType=CreateShipmentEvent.class )
    public void handle( CreateShipmentEvent event) {
	    LOGGER.info("handling CreateShipmentEvent - " + event );
	    Shipment entity = new Shipment();
            entity.setShipmentId( event.getShipmentId() );
            entity.setShipmentNumber( event.getShipmentNumber() );
            entity.setShippedDate( event.getShippedDate() );
            entity.setDeliveredDate( event.getDeliveredDate() );
            entity.setTrackingNumber( event.getTrackingNumber() );
            entity.setShippingAddress( event.getShippingAddress() );
            entity.setStatus( event.getStatus() );
            entity.setCarrier( event.getCarrier() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllShipment( entity );
    }

