    /**
     * Method to retrieve the Shipment via an ShipmentPrimaryKey.
     * @param 	id Long
     * @return 	Shipment
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Shipment handle( FindShipmentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getShipmentId() );
    }
    
    /**
     * Method to retrieve a collection of all Shipments
     *
     * @param	query	FindAllShipmentQuery 
     * @return 	List<Shipment> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Shipment> handle( FindAllShipmentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindShipment,
 * but only if the id matches
 *
 * @param		entity	Shipment
 */
	protected void emitFindShipment( Shipment entity ) {
		LOGGER.info("handling emitFindShipment" );
		
	    queryUpdateEmitter.emit(FindShipmentQuery.class,
	                            query -> query.getFilter().getShipmentId().equals(entity.getShipmentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllShipment
	 * 
	 * @param		entity	Shipment
	 */
	protected void emitFindAllShipment( Shipment entity ) {
		LOGGER.info("handling emitFindAllShipment" );
		
	    queryUpdateEmitter.emit(FindAllShipmentQuery.class,
	                            query -> true,
	                            entity);
	}

